+import test from '"'node:test';
+import assert from 'node:assert/strict';
+import { seedMail, matchesSearch, inFolder, validRecipients } from './mail.js';
+test('seed has unique ids, all required folders and rich conversations',()=>{const mails=seedMail();assert.equal(new Set(mails.map(mail=>mail.id)).size,mails.length);for(const folder of ['Inbox','Drafts','Sent','Trash'])assert.ok(mails.some(mail=>inFolder(mail,folder)));assert.ok(mails.some(mail=>mail.attachments.length>1));assert.ok(mails.some(mail=>mail.count>1));});
+test('search combines text and operators',()=>{const mail=seedMail()[0];assert.equal(matchesSearch(mail,'from:alex is:unread has:attachment label:Work'),true);assert.equal(matchesSearch(mail,'from:sophie'),false);assert.equal(matchesSearch(mail,'\"before we ship\"'),true);assert.equal(matchesSearch(mail,'is:starred in:inbox'),true);assert.equal(matchesSearch(mail,'in:trash'),false);});
+test('starred and labels never include trash; all mail includes archives',()=>{const mail={...seedMail()[0],folder:'Trash'};assert.equal(inFolder(mail,'Starred'),false);assert.equal(inFolder(mail,'Work'),false);assert.equal(inFolder({...mail,folder:'Archive'},'All mail'),true);assert.equal(inFolder({...mail,folder:'Drafts'},'All mail'),false);});
+test('validates one or multiple recipients',()=>{assert.ok(validRecipients('alex@studio.co'));assert.ok(validRecipients('alex@studio.co, maya@example.com'));assert.ok(validRecipients('alex@studio.co;maya@example.com'));assert.equal(validRecipients('oops'),false);assert.equal(validRecipients(''),false);assert.equal(validRecipients('alex@studio.co,invalid'),false);});
